package org.apache.commons.math.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.linear.Array2DRowRealMatrix;
import org.apache.commons.math.linear.CholeskyDecompositionImpl;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CholeskyDecompositionImpl.getDeterminant().
 */
public class CholeskyDecompositionImpl_getDeterminant_TriageGen2Test {

    private static final double DELTA = 1e-12;

    @Test
    public void testGetDeterminant_IdentityMatrix() {
        // The determinant of an identity matrix is 1.
        // Cholesky of I is I. L_ii = 1. Determinant = 1*1 * 1*1 = 1.
        RealMatrix matrix = MatrixUtils.createRealIdentityMatrix(3);
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 1.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testGetDeterminant_DiagonalMatrix() {
        // Matrix: [4, 0; 0, 9]
        // L matrix: [2, 0; 0, 3]
        // Determinant formula in code: (2*2) * (3*3) = 4 * 9 = 36.
        // Note: For Cholesky, det(A) = det(L*L^T) = det(L)^2.
        // Since L is lower triangular, det(L) = product of diagonal.
        // The code calculates (L_ii * L_ii) for each i, which is det(L)^2.
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {4.0, 0.0},
            {0.0, 9.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 36.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testGetDeterminant_GeneralSymmetricPositiveDefinite() {
        // Matrix A = [1, 0.5; 0.5, 1]
        // L = [1, 0; 0.5, sqrt(0.75)]
        // det(L) = 1 * sqrt(0.75) = sqrt(0.75)
        // det(A) = det(L)^2 = 0.75
        // The code calculates sum of squares of diagonals: (1*1) * (sqrt(0.75)*sqrt(0.75)) = 0.75
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {1.0, 0.5},
            {0.5, 1.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 0.75;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testGetDeterminant_SingleElementMatrix() {
        // Matrix [25]
        // L [5]
        // det = 5 * 5 = 25
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {25.0}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        double expected = 25.0;
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, DELTA);
    }

    @Test
    public void testGetDeterminant_LargeValues() {
        // Test for potential precision/overflow handling (though limited by double)
        double val = 1e5;
        RealMatrix matrix = new Array2DRowRealMatrix(new double[][] {
            {val * val, 0.0},
            {0.0, val * val}
        });
        CholeskyDecompositionImpl decomposition = new CholeskyDecompositionImpl(matrix);

        // L_ii = val. det = (val*val) * (val*val) = val^4
        double expected = Math.pow(val, 4);
        double actual = decomposition.getDeterminant();

        Assert.assertEquals(expected, actual, 1e-2); // Larger delta for large numbers
    }
}
